<#
.SYNOPSIS
  Capture lane: wait until the main lane has something for this agent, print it, and exit.

.DESCRIPTION
  Polls GitHub (no model tokens are spent while it sleeps) and returns as soon as one of these appears:
    - a new open issue labelled lane:codex;
    - a new comment on any issue or pull request that is not this agent's own (its comments end with
      "Generated by Codex") and not a bot's;
    - a new commit on the main lane's branch (rebase onto it before continuing).
  Exit codes: 0 = something new (printed below), 3 = nothing new within -MaxMinutes (run it again), 1 = error.
  State (what was already seen) lives in .git/lane-wait.json, never committed. Read-only: it never writes to GitHub.
  Uses `gh api` when the GitHub CLI is signed in (higher rate limit), else the public API without credentials.

.EXAMPLE
  powershell -ExecutionPolicy Bypass -File scripts/lane-wait.ps1 -MaxMinutes 9
#>
param(
    [int]$MaxMinutes = 9,
    [int]$PollSeconds = 180,
    [string]$Branch = 'claude/cool-euler-qjz6mk',
    [string]$Label = 'lane:codex',
    [string]$Signature = 'Generated by Codex'
)

$ErrorActionPreference = 'Stop'

function Get-Repo {
    $url = (git remote get-url origin).Trim()
    if ($url -match 'github\.com[:/]([^/]+)/([^/]+?)(\.git)?$') { return "$($Matches[1])/$($Matches[2])" }
    throw "origin is not a GitHub remote: $url"
}

function Invoke-GitHub([string]$Path) {
    if ($script:UseGh) {
        $json = gh api $Path 2>$null
        if ($LASTEXITCODE -ne 0) { throw "gh api $Path failed" }
        return $json | ConvertFrom-Json
    }
    return Invoke-RestMethod -Uri ("https://api.github.com/" + $Path) -Headers @{ Accept = 'application/vnd.github+json' }
}

function Get-BranchSha {
    $line = git ls-remote origin "refs/heads/$Branch"
    if (-not $line) { return $null }
    return ($line -split "\s+")[0]
}

$repo = Get-Repo
$script:UseGh = $false
if (Get-Command gh -ErrorAction SilentlyContinue) {
    gh auth status *> $null
    $script:UseGh = ($LASTEXITCODE -eq 0)
}

$stateFile = Join-Path (git rev-parse --git-dir).Trim() 'lane-wait.json'
$now = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
if (Test-Path $stateFile) {
    $state = Get-Content $stateFile -Raw | ConvertFrom-Json
} else {
    # First run: start from now (the open issues are read at the start of every session anyway).
    $state = [pscustomobject]@{ since = $now; branch = (Get-BranchSha) }
    $state | ConvertTo-Json | Set-Content $stateFile
    Write-Output "lane-wait: baseline set at $now; waiting for new work."
}

$deadline = (Get-Date).AddMinutes($MaxMinutes)
while ($true) {
    $pollStart = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
    $found = @()
    try {
        $since = [uri]::EscapeDataString($state.since)
        foreach ($i in @(Invoke-GitHub "repos/$repo/issues?labels=$([uri]::EscapeDataString($Label))&state=open&since=$since&per_page=50")) {
            if ([DateTime]$i.created_at -gt [DateTime]$state.since) { $found += "NEW ISSUE #$($i.number): $($i.title)" }
        }

        foreach ($c in @(Invoke-GitHub "repos/$repo/issues/comments?since=$since&per_page=100")) {
            if ($c.user.type -eq 'Bot') { continue }
            if ($c.body -like "*$Signature*") { continue }
            $n = ($c.issue_url -split '/')[-1]
            $first = (($c.body -split "`n") | Where-Object { $_.Trim() } | Select-Object -First 1)
            $found += "COMMENT on #${n}: $first  ($($c.html_url))"
        }

        $sha = Get-BranchSha
        if ($sha -and $sha -ne $state.branch) {
            $found += "MAIN LANE PUSHED $Branch -> $($sha.Substring(0, 7)): fetch and rebase onto it before continuing"
            $state.branch = $sha
        }
    } catch {
        Write-Warning "lane-wait: poll failed ($($_.Exception.Message)); retrying"
    }

    if ($found.Count -gt 0) {
        $state.since = $pollStart
        $state | ConvertTo-Json | Set-Content $stateFile
        $found | ForEach-Object { Write-Output $_ }
        exit 0
    }

    if ((Get-Date) -ge $deadline) {
        Write-Output "lane-wait: nothing new in $MaxMinutes min; run it again to keep waiting."
        exit 3
    }

    Start-Sleep -Seconds ([Math]::Min($PollSeconds, [Math]::Max(1, ($deadline - (Get-Date)).TotalSeconds)))
}
